          w.used = true; noteGame(ev.b, w.who, ev.t);
          out.push({ kind: 'sale', t: ev.t, w0: w.t, p: ev.p || '그립', b: ev.b, buyer: w.who, code: '', name: ev.name, opt: '', qty: w.winners, game: '당첨 ' + w.winners + '명(당첨자 이름 상품)', i: ev.i });
