        // 낙찰 문구 바로 앞(20초 안)에 뜬 장바구니 줄에만 붙인다. 보통은 '낙찰 → 장바구니' 순서라 아래 장바구니 처리에서 짝을 짓는다
        if (lc && !lc.pr && Math.abs(ev.t - lc.t) <= 20000) { lc.pr = true; lc.s.buyer = lc.s.buyer || ev.buyer; out.push({ kind: 'card', t: lc.t, p: '그립', b: ev.b, code: lc.s.code, name: lc.s.name, price: ev.price, i: 0 }); }
