        // 경매 낙찰 뒤 2분 안의 장바구니 줄은 낙찰 상품(1개, 낙찰자). 앞선 선착순 게임 결과('참여자 없음' 등)와 섞지 않는다
        if (au0 && !au0.used && ev.t - au0.t >= 0 && ev.t - au0.t <= 120000) { buyer = au0.buyer; why = '경매 낙찰'; }
