          noteGame(ev.b, buyer, ev.t);
          const sale = { kind: 'sale', t: ev.t, w0: (lastWin[ev.b] && lastWin[ev.b].t) || ev.t, p: '그립', b: ev.b, buyer, code: ev.code, name: (ev.date ? ev.date + ' ' : '') + '#' + ev.code, opt: ev.opt, qty: q, game: why, i: ev.i };
