    var bar = document.createElement('div'); bar.id = '__lwp_bar';
    var txt = document.createElement('span'); txt.id = '__lwp_txt'; txt.textContent = '● ' + PLAT + ' 감지 준비 중… (v' + LW_VERSION + ')';
    var tg = document.createElement('button'); tg.textContent = '펼치기'; tg.style.background = '#1f6feb';
    bar.appendChild(txt); bar.appendChild(tg);
    var panel = document.createElement('div'); panel.id = '__lwp_panel';
    var top = document.createElement('div'); top.id = '__lwp_top';
