        (st.log || []).forEach(function (l) { if (l.status === 'cancel') return; q += l.q; if (l.price != null) rev += l.price * l.q; else unp += l.q; if (l.buyer) buyers[String(l.buyer).replace(/\*+|\.{3}$/g, '')] = 1; });
