        if (/^ch_/.test(k) && Array.isArray(mem[k])) ev = ev.concat(mem[k].map(function (c) { return { t: c.t, kind: '채팅', text: c.m, info: '닉=' + (c.n || ''), sig: 'message-item', p: c.p, b: c.b, u: '', i: c.i || 0 }; }));
